1	<script lang="ts">
2		/**
3		 * Expenses Page
4		 *
5		 * Implements expense categorization feature defined in:
6		 * specs/specifications/expense-categorization.md
7		 * specs/specifications/expense-date-filter.md
8		 *
9		 * Traceable to:
10		 * - #{#exp1a} - Expenses Tab Navigation (IMPLEMENTED)
11		 * - #{#exp1b} - Expenses derived from receipts (IMPLEMENTED)
12		 * - #{#exp9a} - Expense table layout with sorting and selection (IMPLEMENTED)
13		 * - #{#exp6a} - Uncategorized queue view (IMPLEMENTED)
14		 * - #{#exp7a} - Category filter and analytics (IMPLEMENTED)
15		 * - #{#exr1a} - Click expense row to open receipt edit modal (IMPLEMENTED)
16		 * - #{#exr1b} - Integrate existing ReceiptEditModal component (IMPLEMENTED)
17		 * - #{#exr2a} - Make expense rows clickable (IMPLEMENTED)
18		 * - #{#exr2b} - Preserve expenses state after edit (IMPLEMENTED)
19		 * - #{#exp1a} - CSV Export Button (IMPLEMENTED)
20		 * - #{#exp1b} - Respect Current Date Filter (IMPLEMENTED)
21		 * - #{#exp4b} - Integration with Expenses Page (IMPLEMENTED)
22		 * - #{#edf1a} - Expenses View URL Date Filter Integration (IMPLEMENTED)
23		 * - #{#edf4a} - URL Parameter Validation (IMPLEMENTED)
24		 *
25		 * Future enhancements will include:
26		 * - #{#exp2a} - Category assignment UI (partial implementation with CategoryDropdown)
27		 * - #{#exp6b} - Bulk category assignment (UI ready, backend needed)
28		 */
29	
30		import { onMount, untrack } from 'svelte';
31		import { SvelteURLSearchParams } from 'svelte/reactivity';
32		import { page } from '$app/stores';
33		import { goto, replaceState } from '$app/navigation';
34		import { resolve } from '$app/paths';
35		import { supabase } from '$lib/supabaseClient';
36		import { getSignedReceiptUrl, getSignedReceiptUrls } from '$lib/utils/signedUrl';
37		import { ExpenseService, type Expense } from '$lib/services/ExpenseService';
38		import { CategoryService } from '$lib/services/CategoryService';
39		import { ReceiptService } from '$lib/services/ReceiptService';
40		import { CSVExportService } from '$lib/services/CSVExportService';
41		import { PDFExportService } from '$lib/services/PDFExportService';
42		import {
43			readDateFilter,
44			matchesDateRange,
45			applyDateFilterParams,
46			clearDateFilterParams
47		} from '$lib/utils/sharedDateFilter';
48		import { formatDate } from '$lib/utils/dateConversion';
49		import { formatCurrencyWithEstimate } from '$lib/utils/formatCurrency';
50		import { getDefaultFamilyId } from '$lib/utils/familyUtils';
51		import { resolveCategory, buildCategoryMap, findCategoryById } from '$lib/utils/resolveCategory';
52		import { shouldEnablePDFExport } from '$lib/utils/pdfExportState';
53		import { DEFAULT_CATEGORY_COLOR, type Category } from '$lib/types/Category';
54		import type { CategoryGroup } from '$lib/types/Hierarchy';
55		import type { Session } from '@supabase/supabase-js';
56		import type { ReceiptRow } from '$lib/models/Receipt';
57		import CategoryDropdown from '$lib/components/CategoryDropdown.svelte';
58		import ReceiptEditModal from '$lib/components/ReceiptEditModal.svelte';
59		import FilterPanel from '$lib/components/FilterPanel.svelte';
60		import FilteredEmptyState from '$lib/components/FilteredEmptyState.svelte';
61		import Notification from '$lib/components/Notification.svelte';
62		import DataTable from '$lib/components/DataTable.svelte';
63		import { emptySelection } from '$lib/utils/selectionModel';
64	
65		const receiptService = new ReceiptService(supabase);
66	
67		let session: Session | null = $state(null);
68		let familyId: string | null = $state(null);
69		let expenses: Expense[] = $state([]);
70		let categories: Category[] = $state([]);
71		// Spending-hierarchy Groupings, offered when creating a new category inline so
72		// it can be filed straight away rather than landing in Uncategorized.
73		let groups: CategoryGroup[] = $state([]);
74		// #{#rf09} Resolve each row's Category once per (expenses, categories) change
75		// instead of an O(rows × categories) find() per table render.
76		let categoryByReceipt = $derived(buildCategoryMap(expenses, categories));
77		let loading = $state(true);
78		let error: string | null = $state(null);
79		let expenseSelection = $state(emptySelection());
80		let isDeleting = $state(false);
81	
82		// #{#exp6a} - Uncategorized filter state
83		let showUncategorizedOnly = $state(false);
84	
85		// #{#exp7a} - Category filter state
86		let selectedCategoryIds: string[] = $state([]);
87	
88		// #{#edf1a} - URL-based date filter state (read from query parameters)
89		let urlDateFilter = $derived(readDateFilter($page.url.searchParams));
90		let urlDateFrom = $derived(urlDateFilter.dateFrom);
91		let urlDateTo = $derived(urlDateFilter.dateTo);
92	
93		// #{#edf1a} - Temporary date filter inputs (before "Apply" is clicked)
94		let tempFilterDateFrom = $state('');
95		let tempFilterDateTo = $state('');
96	
97		// #{#edf1a} - Sync temp values when URL changes
98		$effect(() => {
99			tempFilterDateFrom = urlDateFrom;
100			tempFilterDateTo = urlDateTo;
101		});
102	
103		// #{#exr1b} - Receipt edit modal state
104		let editingReceipt: ReceiptRow | null = $state(null);
105		let editingExpense: Expense | null = $state(null);
106		let showEditModal = $state(false);
107		let isSaving = $state(false);
108		let successMessage: string | null = $state(null);
109	
110		// #{#exp1a} #{#exp3b} - CSV Export state
111		let isExporting = $state(false);
112		const csvService = new CSVExportService();
113	
114		// #{#cre1a} #{#cre4a} - PDF Export state
115		let isExportingPDF = $state(false);
116		let pdfExportProgress = $state('');
117		let pdfAbortController: AbortController | null = $state(null);
118		const pdfService = new PDFExportService();
119	
120		onMount(async () => {
121			// #{#exp1a} Criterion 7: Verify authentication
122			const { data } = await supabase.auth.getSession();
123			session = data.session;
124	
125			if (!session) {
126				return;
127			}
128	
129			// Get user's default family
130			familyId = await getDefaultFamilyId();
131	
132			if (!familyId) {
133				error = 'No family found. Please contact support.';
134				return;
135			}
136	
137			// #{#exp1b} Load expenses derived from receipts
138			await loadExpenses();
139	
140			// Load family categories for dropdown
141			await loadCategories();
142	
143			// #{#vca5a} Check for auto-categorization matches on page load
144			await checkForAutoCategorizationMatches();
145		});
146	
147		/**
148		 * Load expenses from receipts using ExpenseService
149		 * #{#exp1b} - Expenses derived from receipts
150		 */
151		async function loadExpenses() {
152			if (!session?.user) return;
153	
154			try {
155				loading = true;
156				error = null;
157	
158				const expenseService = new ExpenseService(supabase);
159				expenses = await expenseService.getExpenses(session.user.id);
160			} catch (err) {
161				console.error('Error loading expenses:', err);
162				error = err instanceof Error ? err.message : 'Failed to load expenses';
163			} finally {
164				loading = false;
165			}
166		}
167	
168		// #{#exp6b} Selection-based bulk delete. An expense IS a receipt (1:1, computed),
169		// so this deletes the underlying receipts (record + stored file).
170		async function deleteSelected(): Promise<void> {
171			const receiptIds = Array.from(expenseSelection.selected);
172			if (receiptIds.length === 0) return;
173			if (
174				!confirm(
175					`Delete ${receiptIds.length} selected expense${receiptIds.length === 1 ? '' : 's'}? This removes the underlying receipt and its stored file.`
176				)
177			) {
178				return;
179			}
180	
181			isDeleting = true;
182			error = null;
183			const originalExpenses = expenses;
184			// Optimistic update — remove from UI immediately
185			expenses = expenses.filter((e) => !expenseSelection.selected.has(e.receipt_id));
186	
187			try {
188				await receiptService.bulkDeleteReceipts(receiptIds);
189				expenseSelection = emptySelection();
190				showToast(
191					`Deleted ${receiptIds.length} expense${receiptIds.length === 1 ? '' : 's'}`,
192					'success'
193				);
194			} catch (err) {
195				// Rollback on failure
196				expenses = originalExpenses;
197				error = err instanceof Error ? err.message : 'Failed to delete expenses';
198			} finally {
199				isDeleting = false;
200			}
201		}
202	
203		// Apply one category to many expenses in a single batched upsert. Used when the
204		// user picks a category on a row that is part of a multi-row selection — the
205		// change fans out to the whole selection. Unlike the single-row flow it does
206		// NOT auto-create a vendor rule: the selection spans many merchants, so there
207		// is no one merchant to attach a rule to.
208		async function applyCategoryToSelection(receiptIds: string[], category: Category): Promise<void> {
209			error = null;
210			try {
211				const expenseService = new ExpenseService(supabase);
212				await expenseService.bulkAssignCategory(receiptIds, category.id, 'manual');
213				expenseSelection = emptySelection();
214				await loadExpenses();
215				showToast(`Set ${receiptIds.length} expenses to ${category.name}`, 'success');
216			} catch (err) {
217				error = err instanceof Error ? err.message : 'Failed to recategorize expenses';
218			}
219		}
220	
221		/**
222		 * Check for and apply vendor rule matches to uncategorized expenses
223		 * #{#vca5a} - Batch Auto-Categorization on Page Load
224		 */
225		async function checkForAutoCategorizationMatches() {
226			if (!familyId) return;
227	
228			try {
229				const expenseService = new ExpenseService(supabase);
230	
231				// Apply all family vendor rules to current expenses
232				const totalAssigned = await expenseService.applyAllVendorRules(familyId, expenses);
233	
234				// If any expenses were auto-assigned, reload and notify user
235				if (totalAssigned > 0) {
236					await loadExpenses();
237					showToast(
238						`Auto-categorized ${totalAssigned} expense${totalAssigned === 1 ? '' : 's'} based on vendor rules`,
239						'success'
240					);
241				}
242			} catch (err) {
243				console.error('Error checking auto-categorization:', err);
244				// Don't show error to user - this is a background operation
245			}
246		}
247	
248		/**
249		 * Load family categories for dropdown
250		 * #{#exp2a} - Category Assignment UI
251		 * #{#exp3a} - Auto-initialize default categories for new families
252		 */
253		async function loadCategories() {
254			if (!familyId) return;
255	
256			try {
257				const categoryService = new CategoryService(supabase);
258				categories = await categoryService.getFamilyCategories(familyId);
259	
260				// Auto-initialize default categories for families with no categories
261				// #{#exp3a} Requirement 2 & 3
262				if (categories.length === 0) {
263					await categoryService.createDefaultCategories(familyId);
264					categories = await categoryService.getFamilyCategories(familyId);
265				}
266	
267				// Groupings power the "Group" selector in inline category creation.
268				// Best-effort: a family without a seeded hierarchy simply gets no
269				// selector (the feature degrades to the previous behaviour).
270				groups = await categoryService.getFamilyGroups(familyId);
271			} catch (err) {
272				console.error('Error loading categories:', err);
273			}
274		}
275	
276		/**
277		 * Handle category assignment
278		 * #{#exp2a} - Category Assignment UI
279		 * #{#exp5b} - Manual Override Precedence
280		 * #{#exp5a} - Auto-create vendor rules on first categorization
281		 */
282		async function handleCategorySelect(receiptId: string, category: Category) {
283			// If this row is part of a multi-row selection, the pick fans out to every
284			// selected expense (no separate bulk control needed). A single checked row
285			// falls through to the normal single-row path so its vendor rule is still
286			// auto-created.
287			const selected = expenseSelection.selected;
288			if (selected.has(receiptId) && selected.size > 1) {
289				await applyCategoryToSelection(Array.from(selected), category);
290				return;
291			}
292	
293			try {
294				const expenseService = new ExpenseService(supabase);
295	
296				// 1. Assign category to this expense
297				await expenseService.assignCategory(receiptId, category.id, 'manual');
298	
299				// 2. Auto-create vendor rule if none exists
300				// Find the expense to get merchant_name
301				const expense = expenses.find((e) => e.receipt_id === receiptId);
302				if (expense && familyId) {
303					// Check if rule already exists
304					const existingRule = await expenseService.getVendorRule(familyId, expense.merchant_name);
305	
306					// Only create rule if none exists (silent auto-creation)
307					if (!existingRule) {
308						await expenseService.createVendorRule(familyId, expense.merchant_name, category.id);
309	
310						// #{#vca1a} Apply rule to visible expenses after creating it
311						const vendorPattern = expenseService.normalizeVendor(expense.merchant_name);
312						const appliedCount = await expenseService.applyRuleToVisibleExpenses(
313							filteredExpenses,
314							vendorPattern,
315							category.id
316						);
317	
318						// #{#vca3a} Show user feedback if expenses were auto-assigned
319						if (appliedCount > 0) {
320							showToast(
321								`Applied ${category.name} to ${appliedCount} matching expense${appliedCount === 1 ? '' : 's'}`,
322								'success'
323							);
324						}
325					}
326					// If rule exists, user must click "change default" in dropdown to update it
327				}
328	
329				// 3. Reload expenses to reflect the change
330				await loadExpenses();
331			} catch (err) {
332				console.error('Error assigning category:', err);
333				error = err instanceof Error ? err.message : 'Failed to assign category';
334			}
335		}
336	
337		/**
338		 * Handle inline category creation from CategoryDropdown
339		 * #{#exp3b} - Create New Category Inline
340		 */
341		async function handleCreateNewCategory(data: {
342			name: string;
343			color: string | null;
344			groupId: string | null;
345		}) {
346			try {
347				const categoryService = new CategoryService(supabase);
348				await categoryService.createCategory(
349					familyId || '',
350					data.name,
351					data.color || undefined,
352					data.groupId
353				);
354				await loadCategories();
355				showToast(`Created category: ${data.name}`, 'success');
356			} catch (err) {
357				console.error('Error creating category:', err);
358				showToast(err instanceof Error ? err.message : 'Failed to create category', 'error');
359			}
360		}
361	
362		/**
363		 * Handle vendor rule creation from CategoryDropdown
364		 * #{#vca1a} - Apply rules to visible expenses when rule is created/updated
365		 * #{#vca3a} - Show user feedback for auto-assignment
366		 */
367		async function handleVendorRuleCreated(data: { merchantName: string; categoryId: string }) {
368			try {
369				const { merchantName, categoryId } = data;
370				const expenseService = new ExpenseService(supabase);
371	
372				// Get category name for feedback
373				const category = findCategoryById(categories, categoryId);
374				if (!category) return;
375	
376				// Apply rule to visible expenses
377				const vendorPattern = expenseService.normalizeVendor(merchantName);
378				const appliedCount = await expenseService.applyRuleToVisibleExpenses(
379					filteredExpenses,
380					vendorPattern,
381					categoryId
382				);
383	
384				// Show user feedback
385				if (appliedCount > 0) {
386					showToast(
387						`Applied ${category.name} to ${appliedCount} matching expense${appliedCount === 1 ? '' : 's'}`,
388						'success'
389					);
390				}
391	
392				// Reload expenses to reflect the changes
393				await loadExpenses();
394			} catch (err) {
395				console.error('Error applying vendor rule:', err);
396				error = err instanceof Error ? err.message : 'Failed to apply vendor rule';
397			}
398		}
399	
400		// formatCurrency imported from $lib/utils/formatCurrency
401	
402		// formatDate imported from $lib/utils/dateConversion
403	
404		/**
405		 * #{#exp6a} Criterion 2: Filter uncategorized expenses
406		 * #{#exp7a} Criterion 2 & 4: Filter by category (OR logic for multiple)
407		 * #{#edf1a} Criterion 6 & 8: Filter by date range from URL (works with category filters)
408		 */
409		let filteredExpenses = $derived(
410			expenses.filter((expense) => {
411				// #{#edf1a} Date range filter (from URL parameters)
412				if (!matchesDateRange(expense.transaction_date, urlDateFrom, urlDateTo)) {
413					return false;
414				}
415	
416				// #{#exp6a} Uncategorized filter takes precedence
417				if (showUncategorizedOnly) {
418					return expense.category_id === null;
419				}
420	
421				// #{#exp7a} Category filter (OR logic)
422				if (selectedCategoryIds.length > 0) {
423					return expense.category_id && selectedCategoryIds.includes(expense.category_id);
424				}
425	
426				// No filters active, show all
427				return true;
428			})
429		);
430	
431		/**
432		 * #{#exp6a} Criterion 3: Count uncategorized expenses
433		 * #{#flt1a} Use filteredExpenses to reflect current filter state
434		 */
435		let uncategorizedCount = $derived(filteredExpenses.filter((e) => e.category_id === null).length);
436	
437		/**
438		 * #{#exp7a} Criterion 3: Count expenses per category
439		 * #{#flt1a} Use filteredExpenses to reflect current filter state
440		 */
441		let expenseCountByCategory = $derived(
442			filteredExpenses.reduce(
443				(acc, expense) => {
444					const key = expense.category_id || 'uncategorized';
445					acc[key] = (acc[key] || 0) + 1;
446					return acc;
447				},
448				{} as Record<string, number>
449			)
450		);
451	
452		/**
453		 * #{#cre1a} #{#cre1b} #{#cre4a} PDF export button state
454		 * RF-13: pure predicate lives in $lib/utils/pdfExportState
455		 */
456		let pdfExportEnabled = $derived(
457			shouldEnablePDFExport({
458				filteredExpensesCount: filteredExpenses.length,
459				selectedCategoryIds,
460				showUncategorizedOnly,
461				isExporting: isExportingPDF
462			})
463		);
464	
465		/**
466		 * #{#exp6a} Criterion 1 & 5: Toggle uncategorized filter
467		 */
468		function toggleUncategorizedFilter() {
469			showUncategorizedOnly = !showUncategorizedOnly;
470			// Clear category filter when showing uncategorized
471			if (showUncategorizedOnly) {
472				selectedCategoryIds = [];
473			}
474			updateURL();
475		}
476	
477		/**
478		 * #{#exp7a} Toggle category selection
479		 */
480		function toggleCategoryFilter(categoryId: string) {
481			if (selectedCategoryIds.includes(categoryId)) {
482				selectedCategoryIds = selectedCategoryIds.filter((id) => id !== categoryId);
483			} else {
484				selectedCategoryIds = [...selectedCategoryIds, categoryId];
485			}
486			// Clear uncategorized filter when selecting categories
487			if (selectedCategoryIds.length > 0) {
488				showUncategorizedOnly = false;
489			}
490			updateURL();
491		}
492	
493		/**
494		 * #{#exp7a} Clear all category filters
495		 */
496		function clearCategoryFilter() {
497			selectedCategoryIds = [];
498			updateURL();
499		}
500	
501		/**
502		 * #{#edf1a} Criterion 2: Apply date filters to URL
503		 */
504		function applyFilterValues(): void {
505			const params = applyDateFilterParams(
506				$page.url.searchParams,
507				tempFilterDateFrom,
508				tempFilterDateTo
509			);
510			goto(resolve(`/expenses?${params.toString()}`), { replaceState: true, keepFocus: true });
511		}
512	
513		/**
514		 * #{#edf1a} Criterion 3: Clear all filters (date + category)
515		 */
516		function clearClientFilters(): void {
517			// Clear URL date filters
518			const params = clearDateFilterParams($page.url.searchParams);
519			goto(resolve(`/expenses?${params.toString()}`), { replaceState: true, keepFocus: true });
520	
521			// Reset temp date filter inputs
522			tempFilterDateFrom = '';
523			tempFilterDateTo = '';
524	
525			// Clear category filters
526			showUncategorizedOnly = false;
527			selectedCategoryIds = [];
528			updateURL();
529		}
530	
531		/**
532		 * #{#exp6a} Criterion 7 & #{#exp7a}: Update URL with filter state
533		 */
534		function updateURL() {
535			const params = new SvelteURLSearchParams();
536	
537			if (showUncategorizedOnly) {
538				params.set('filter', 'uncategorized');
539			} else if (selectedCategoryIds.length > 0) {
540				params.set('category', selectedCategoryIds.join(','));
541			}
542	
543			const query = params.toString();
544			replaceState(query ? resolve(`/expenses?${query}`) : resolve('/expenses'), {});
545		}
546	
547		/**
548		 * #{#exp6a} Criterion 7 & #{#exp7a}: Restore filter state from URL on mount
549		 */
550		onMount(() => {
551			const params = new URLSearchParams(window.location.search);
552			const filter = params.get('filter');
553			const category = params.get('category');
554	
555			if (filter === 'uncategorized') {
556				showUncategorizedOnly = true;
557			} else if (category) {
558				selectedCategoryIds = category.split(',');
559			}
560		});
561	
562		/**
563		 * #{#exr1a} Open receipt edit modal when clicking expense row
564		 * #{#exr1b} Convert Expense to ReceiptRow format for modal
565		 */
566		function openReceiptEditModal(expense: Expense) {
567			editingExpense = expense;
568			editingReceipt = {
569				id: expense.receipt_id,
570				user_id: session?.user?.id || '',
571				merchant_name: expense.merchant_name,
572				transaction_date: expense.transaction_date,
573				total_amount: expense.total_amount,
574				receipt_image_path: expense.receipt_image_path ?? null,
575				tax: null,
576				currency: expense.currency,
577				exchange_rate_to_cad: expense.exchange_rate_to_cad,
578				credit_card_name: null,
579				credit_card_last_4: null,
580				created_at: new Date().toISOString(),
581				matched_transaction_id: null,
582				suspicious_date: false,
583				original_filename: null // #{#ofn1a} display-only; not carried on Expense
584			};
585			showEditModal = true;
586		}
587	
588		/**
589		 * #{#exr1b} Handle receipt save event from modal
590		 * #{#exr2b} Preserve state by reloading expenses without changing filters
591		 */
592		async function handleReceiptSave(updatedReceipt: ReceiptRow) {
593			isSaving = true;
594			error = null;
595	
596			try {
597				await receiptService.update(updatedReceipt.id, {
598					merchant_name: updatedReceipt.merchant_name,
599					transaction_date: updatedReceipt.transaction_date,
600					total_amount: updatedReceipt.total_amount,
601					tax: updatedReceipt.tax,
602					currency: updatedReceipt.currency,
603					exchange_rate_to_cad: updatedReceipt.exchange_rate_to_cad,
604					credit_card_name: updatedReceipt.credit_card_name,
605					credit_card_last_4: updatedReceipt.credit_card_last_4,
606					receipt_image_path: updatedReceipt.receipt_image_path,
607					matched_transaction_id: updatedReceipt.matched_transaction_id,
608					suspicious_date: updatedReceipt.suspicious_date
609				});
610	
611				showEditModal = false;
612				editingReceipt = null;
613				editingExpense = null;
614	
615				// #{#exr2b} Reload expenses to show updated data
616				await loadExpenses();
617	
618				// Show success message
