640		/**
641		 * #{#exp1a} #{#exp4b} Handle CSV export
642		 * #{#exp1b} Respects current filter (exports filteredExpenses)
643		 * #{#exp3b} Shows loading state and feedback
644		 * #{#edf2a} CSV export respects date filters and includes date range in filename
645		 */
646		async function handleExportCSV() {
647			// #{#exp1a} Criterion 3: Disabled when no expenses
648			if (filteredExpenses.length === 0) {
649				return;
650			}
651	
652			isExporting = true;
653			try {
654				// #{#exp4b} Criterion 2: Export filtered expenses
655				const csvContent = csvService.exportExpensesToCSV(filteredExpenses);
656	
657				// #{#edf2a} Criterion 2: Generate filename based on current filters
658				// (date range wins over category filters — logic in CSVExportService).
659				const filename = csvService.expenseExportFilename({
660					dateFrom: urlDateFrom,
661					dateTo: urlDateTo,
662					uncategorizedOnly: showUncategorizedOnly,
663					selectedCategoryNames: selectedCategoryIds.map(
664						(id) => findCategoryById(categories, id)?.name ?? ''
665					)
666				});
667	
668				// #{#exp3a} Criterion 1: Download CSV
669				csvService.downloadCSV(csvContent, filename);
670	
671				// #{#exp3b} Criterion 3: Success feedback
672				showToast(
673					`CSV exported successfully: ${filteredExpenses.length} expense${filteredExpenses.length !== 1 ? 's' : ''}`,
674					'success'
675				);
676			} catch (err) {
677				// #{#exp3b} Criterion 4: Error feedback
678				console.error('Error exporting CSV:', err);
679				showToast(
680					`Failed to export CSV: ${err instanceof Error ? err.message : 'Unknown error'}`,
681					'error'
682				);
683			} finally {
684				isExporting = false;
685			}
686		}
