760		/**
761		 * Show toast notification
762		 * #{#exp3b} Criterion 3, 4: Success/error feedback
763		 */
764		function showToast(message: string, type: 'success' | 'error') {
765			successMessage = message;
766			setTimeout(
767				() => {
768					successMessage = null;
769				},
770				type === 'success' ? 3000 : 5000
771			);
772		}
